	/* @Override */
	public bool goTo(Address goToAddress) {
		if (goToAddress == null) {
			return false;
		}
		ProgramLocation programLocation = null;
		Program program = defaultNavigatable.getProgram();
		// override has precedence
		if (override != null) {
