	/* @Override */
	public bool goToQuery(Navigatable navigatable, Address fromAddr, QueryData queryData,
			GoToServiceListener listener, TaskMonitor monitor) {

		if (navigatable == null || navigatable.isConnected()) {
			navigatable = defaultNavigatable;
		}

		GoToQuery query = new GoToQuery(navigatable, plugin, this, queryData, fromAddr,
			helper.getOptions(), monitor);

		bool result;
		try {
			result = query.processQuery();
			if (listener != null) {
